1	// 素朴な CSV パーサ(ダブルクォート内のカンマに対応)。1行目はヘッダー。
2	export function parseCsv(text) {
3	  const lines = text.split(/\r?\n/).filter((l) => l.length > 0)
4	  const header = splitLine(lines[0])
5	  return lines.slice(1).map((line) => Object.fromEntries(splitLine(line).map((v, i) => [header[i], v])))
6	}
7	
8	function splitLine(line) {
9	  const out = []
10	  let cur = ''
11	  let quoted = false
12	  for (const ch of line) {
13	    if (ch === '"') quoted = !quoted
14	    else if (ch === ',' && !quoted) {
15	      out.push(cur)
16	      cur = ''
17	    } else cur += ch
18	  }
19	  out.push(cur)
20	  return out
21	}
