import { readFileSync } from 'node:fs'
import { parseCsv } from './parse.js'

const UTF8_BOM = Buffer.from([0xef, 0xbb, 0xbf])

// 取引先の CSV を読み込んで行の配列にする。
// 文字コードは BOM 付き UTF-8 / BOM なし UTF-8 / CP932(Shift_JIS) を自動判定する。
export function readCsv(path) {
  const buffer = readFileSync(path)
  return parseCsv(decodeCsv(buffer))
}

function decodeCsv(buffer) {
  if (buffer.subarray(0, 3).equals(UTF8_BOM)) {
    return new TextDecoder('utf-8').decode(buffer.subarray(3))
  }
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(buffer)
  } catch {
    // BOM がなく UTF-8 として不正な場合、Excel が出力する CP932(Shift_JIS) とみなす。
    return new TextDecoder('shift_jis').decode(buffer)
  }
}

